/// Accept exactly `https://<host>[:port]`, no path, query, fragment or
/// userinfo: the value is used as a URL prefix, so anything else would let
/// the deployment secret smuggle a different target into the redirect.
pub fn parse_broker_origin(raw: &str) -> Option<String> {
    let origin = raw.trim().trim_end_matches('/');
    let host = origin.strip_prefix("https://")?;
    let mut bytes = host.bytes();
    let first_ok = bytes.next().is_some_and(|b| b.is_ascii_alphanumeric());
    let rest_ok = bytes.all(|b| b.is_ascii_alphanumeric() || matches!(b, b'.' | b'-' | b':'));
    (first_ok && rest_ok).then(|| origin.to_string())
}

