/// Gate one request for the property named `client_id`.
///
/// `Some(reply)` means answer with this and stop. `None` means a valid
/// session: carry on into the application.
///
/// A missing shared secret refuses every request rather than letting them
/// through: a property that cannot verify sessions must not serve. A missing
/// broker origin refuses only the visitors who would have to be sent there;
/// verified sessions and the callback need the key, not the broker.
pub async fn gate(ctx: &AppContext, req: &IngressRequest, client_id: &str) -> Option<IngressReply> {
    // A fragment is never part of a request target; one here is a parser
    // differential waiting to happen (`/_sso/logout#?x`), so refuse it.
    if req.path.contains('#') {
        return Some(text(req, 400, "fragments are not valid request targets"));
    }
    let Some(secret) = usable_secret(ctx) else {
        tracing::error!(
            target: "ferrite_sso::gate",
            "'{}' is not bound or is too short; refusing every request rather than serving ungated",
            SSO_SECRET
        );
        return Some(text(req, 503, &not_configured(MissingSecret::SharedKey)));
    };
    let sso = SsoClientConfig {
        client_id: client_id.to_string(),
        // Filled in only for the redirect; the callback and session paths
        // never read it.
        broker_origin: String::new(),
        key: AssertionKey::from_secret(&secret),
    };
    let now_ms = ctx.now_ms();
    let (path, query) = split_target(&req.path);
    let current = match session_on(ctx, req, client_id).await {
        Ok(current) => current,
        Err(error) => {
            tracing::error!(target: "ferrite_sso::gate", %error, "the session store could not answer");
            return Some(text(req, 503, "the session store is unavailable"));
        }
    };

    if path == CALLBACK_PATH {
        if let Some(refusal) = callback_refusal(req) {
            return Some(refusal);
        }
        // A browser that already holds a valid session keeps it: a callback
        // planted by another site must not swap the visitor into someone
        // else's account.
        if current.is_some() {
            return Some(redirect(req, "/"));
        }
        return Some(callback(ctx, req, &sso, query, now_ms, SubjectForm::AsAsserted).await);
    }
    if path == LOGOUT_PATH {
        return Some(logout(ctx, req, client_id, current.as_ref(), SignOut::ThisSession).await);
    }

    if let Some(claims) = &current {
        if !(wants_html(req) && needs_renewal(claims, now_ms)) {
            return None;
        }
        // Renew through the broker, which rechecks the access list. The old
        // cookie goes with this reply, so the callback mints afresh and a
        // person the broker no longer admits is signed out here.
        if let Some(broker) = broker_origin(ctx) {
            let sso = SsoClientConfig { broker_origin: broker, ..sso };
            return Some(renewal(req, &sso, path));
        }
        return None;
    }

    // The anonymous liveness probe: answered here, never by the application
    // (see [`HEALTH_PATH`]). 200 only when a signed-out visitor could in fact
    // be sent to sign in.
    if is_health_probe(req) {
        return Some(match broker_origin(ctx) {
            Some(_) => text(req, 200, HEALTH_BODY),
            None => text(req, 503, &not_configured(MissingSecret::BrokerOrigin)),
        });
    }

    // Only a document navigation is worth redirecting: a machine caller told
    // to follow a 303 would treat the sign-in page as the answer.
    if !wants_html(req) {
        return Some(text(req, 401, "authentication required"));
    }
    let Some(broker) = broker_origin(ctx) else {
        tracing::error!(
            target: "ferrite_sso::gate",
            "'{}' is not bound or is not an https origin; a signed-out visitor cannot be sent to sign in",
            SSO_BROKER_ORIGIN
        );
        return Some(text(req, 503, &not_configured(MissingSecret::BrokerOrigin)));
    };
    let sso = SsoClientConfig { broker_origin: broker, ..sso };
    Some(redirect(req, &sso.start_url(Some(path))))
}

/// [`gate`] for a property that is open to everyone: no request needs a session.
///
/// The demonstrations are reachable by anyone with the link, so a
/// signed-out visitor reaches the application instead of being sent to sign
/// in. The gate still completes the sign-in callback and sign-out, so a page
/// that offers sign-in keeps working, and still answers the anonymous health
/// probe itself. An application that wants to know who is signed in asks
/// [`signed_in`], which is `None` for an anonymous visitor.
pub async fn open_gate(
    ctx: &AppContext,
    req: &IngressRequest,
    client_id: &str,
) -> Option<IngressReply> {
    if req.path.contains('#') {
        return Some(text(req, 400, "fragments are not valid request targets"));
    }
    let (path, _) = split_target(&req.path);
    if path == CALLBACK_PATH || path == LOGOUT_PATH || is_health_probe(req) {
        return gate(ctx, req, client_id).await;
    }
    // A signed-in visitor's session is renewed on navigation as behind the
    // closed gate, so it is rechecked against the access list and does not
    // lapse mid-visit. Anyone else, and any store failure, simply passes:
    // the property is open, and `signed_in` answers who is signed in.
    if !wants_html(req) || cookie_value(&req.headers, SESSION_COOKIE).is_none() {
        return None;
    }
    let claims = session_on(ctx, req, client_id).await.ok().flatten()?;
    if !needs_renewal(&claims, ctx.now_ms()) {
        return None;
    }
    let secret = usable_secret(ctx)?;
    let sso = SsoClientConfig {
        client_id: client_id.to_string(),
        broker_origin: broker_origin(ctx)?,
        key: AssertionKey::from_secret(&secret),
    };
    Some(renewal(req, &sso, path))
}

/// Send a navigation through the broker to renew its session, clearing the
/// old cookie on the way.
fn renewal(req: &IngressRequest, sso: &SsoClientConfig, path: &str) -> IngressReply {
    let mut reply = redirect(req, &sso.start_url(Some(path)));
    if let Ok(cookie) = ResponseCookie::clear(SESSION_COOKIE) {
        reply.headers.push(("set-cookie".into(), cookie));
    }
    reply
}

/// What a sign-out ends.
#[derive(Clone, Copy, PartialEq, Eq)]
pub(super) enum SignOut {
    /// This browser's session, every copy of its cookie included.
    ThisSession,
    /// Every session of this person at this property.
    EverySession,
}

/// Sign-out: end the session (or, for the scoped gate, every session of this
/// person at this property) and clear the cookie.
///
/// A sign-out link is an ordinary same-origin navigation, so `GET` keeps
/// working, but a request the browser marks as coming from another site (an
/// `<img>` or a link on a sibling host) or as a prefetch signs nobody out.
pub(super) async fn logout(
    ctx: &AppContext,
    req: &IngressRequest,
    client_id: &str,
    current: Option<&SessionClaims>,
    scope: SignOut,
) -> IngressReply {
    let header = |name: &str| {
        req.headers
            .iter()
            .find(|(key, _)| key.eq_ignore_ascii_case(name))
            .map(|(_, value)| value.trim().to_ascii_lowercase())
    };
    if header("sec-fetch-site").is_some_and(|site| site != "same-origin" && site != "none") {
        return text(req, 403, "sign-out must come from this site");
    }
    if header("sec-purpose").or_else(|| header("purpose")).is_some_and(|p| p.contains("prefetch")) {
        return text(req, 403, "sign-out is never prefetched");
    }
    let clear = ResponseCookie::clear(SESSION_COOKIE).ok();
    let mut reply = match current {
        Some(claims) => match match scope {
            SignOut::ThisSession => revoke_session(ctx, client_id, claims).await,
            SignOut::EverySession => revoke_sessions(ctx, client_id, &claims.user).await,
        } {
            Ok(()) => redirect(req, "/"),
            Err(reason) => {
                tracing::error!(target: "ferrite_sso::gate", reason, "sign-out could not end the session");
                text(req, 503, reason)
            }
        },
        None => redirect(req, "/"),
    };
    if let Some(cookie) = clear {
        reply.headers.push(("set-cookie".into(), cookie));
    }
    reply
}

/// What [`gate_reply`] and [`open_gate_reply`] did with a request.
#[must_use]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum GateReply {
    /// A verified session (or an open property's ordinary path): carry on
    /// into the application.
    Pass,
    /// The gate answered and its reply was published: acknowledge the lease.
    Answered,
    /// The gate answered but its reply could not be published. The request
    /// must still not reach the application, and its lease must NOT be
    /// acknowledged, so the queue redelivers it instead of leaving the
    /// caller waiting for a reply that will never come.
    Unpublished,
}

impl GateReply {
    /// Whether the gate dealt with the request (do not run the application).
    pub fn handled(self) -> bool {
        !matches!(self, GateReply::Pass)
    }

    /// Whether the request's lease may be acknowledged.
    pub fn ack(self) -> bool {
        matches!(self, GateReply::Answered)
    }
}

/// [`gate_reply`] for a property that is open to everyone; see [`open_gate`].
pub async fn open_gate_reply(ctx: &AppContext, req: &IngressRequest, client_id: &str) -> GateReply {
    let Some(reply) = open_gate(ctx, req, client_id).await else {
        return GateReply::Pass;
    };
    publish_gate_reply(ctx, req, &reply).await
}

